// Editorial Style Tokens - Precise class mappings for AI
import { createStyleTokens } from "./token-defaults";

export const editorialTokens = createStyleTokens({
  border: {
    width: "border",
    color: "border-border",
    radius: "rounded-none",
    style: "border-solid",
  },

  shadow: {
    sm: "shadow-none",
    md: "shadow-none",
    lg: "shadow-none",
    none: "shadow-none",
    hover: "shadow-none",
    focus: "shadow-none",
  },

  interaction: {
    hoverOpacity: "hover:opacity-90",
    transition: "transition-colors duration-200",
  },

  typography: {
    heading: "font-serif tracking-tight",
    body: "font-sans",
    mono: "font-mono",
    sizes: {
      hero: "text-4xl md:text-6xl lg:text-7xl",
      h1: "text-3xl md:text-5xl",
      h2: "text-2xl md:text-3xl",
      h3: "text-xl md:text-2xl",
      body: "text-sm md:text-base",
      small: "text-xs",
    },
  },

  spacing: {
    section: "py-16 md:py-24 lg:py-32",
    container: "px-6 md:px-12",
    card: "p-6",
    gap: {
      sm: "gap-4",
      md: "gap-6 md:gap-8",
      lg: "gap-8 md:gap-12",
    },
  },

  colors: {
    background: {
      primary: "bg-background",
      secondary: "bg-foreground",
      accent: ["bg-[#e63946]"],
    },
    text: {
      primary: "text-foreground",
      secondary: "text-background",
      muted: "text-muted",
    },
    button: {
      primary: "bg-foreground text-background",
      secondary: "bg-transparent text-foreground",
    },
  },

  forbidden: {
    classes: [
      // No rounded corners
      "rounded-sm", "rounded", "rounded-md", "rounded-lg", "rounded-xl", "rounded-2xl", "rounded-3xl", "rounded-full",
      // No shadows
      "shadow-sm", "shadow", "shadow-md", "shadow-lg", "shadow-xl", "shadow-2xl",
      // No thick borders
      "border-2", "border-4", "border-8",
      // No bright colors
      "bg-blue-500", "bg-green-500", "bg-yellow-500", "bg-purple-500", "bg-pink-500",
      // No gradients
      "bg-gradient-to-r", "bg-gradient-to-l", "bg-gradient-to-t", "bg-gradient-to-b",
      // No bold headings (Editorial uses font-normal for serif)
      "font-black", "font-extrabold",
    ],
    patterns: [
      "^rounded-(?!none)",           // Any rounded except rounded-none
      "^shadow-(?!none)",            // Any shadow
      "^border-[248]",               // Thick borders
      "^bg-gradient-",               // Any gradient
    ],
    reasons: {
      "rounded-lg": "Editorial uses sharp corners only (rounded-none)",
      "shadow-lg": "Editorial avoids shadows completely",
      "border-4": "Editorial uses thin borders only (border)",
      "bg-gradient-to-r": "Editorial uses solid colors, no gradients",
      "font-black": "Editorial headings use font-serif with normal weight, not bold",
    },
  },

  required: {
    button: [
      "px-6 py-3",
      "text-sm tracking-wide",
      "transition-colors",
    ],
    card: [
      "border border-border",
      "hover:border-foreground",
      "transition-colors",
    ],
    input: [
      "border border-border",
      "text-sm",
      "focus:outline-none",
      "focus:border-foreground",
      "transition-colors",
      "placeholder:text-muted",
    ],
  },
});

// Editorial Component Recipes
import { createStyleRecipes } from "./factory";

export const editorialRecipes = createStyleRecipes("editorial", "Editorial", {
    button: {
      id: "button",
      name: "Button",
      nameZh: "按钮",
      description: "Editorial button with hover-underline animation and uppercase tracking",
      skeleton: {
        element: "button",
        baseClasses: [
          "font-sans",
          "tracking-[0.2em]",
          "uppercase",
          "text-xs",
          "relative",
          "pb-1",
          "transition-colors duration-200",
        ],
      },
      parameters: [
        {
          id: "size",
          label: "Size",
          labelZh: "尺寸",
          type: "select",
          options: [
            { value: "sm", label: "Small", labelZh: "小", classes: "text-[10px]" },
            { value: "md", label: "Medium", labelZh: "中", classes: "text-xs" },
            { value: "lg", label: "Large", labelZh: "大", classes: "text-sm" },
          ],
          default: "md",
        },
        {
          id: "withArrow",
          label: "Arrow Icon",
          labelZh: "箭头图标",
          type: "boolean",
          default: false,
          trueClasses: "flex items-center gap-4 group",
        },
      ],
      variants: {
        primary: {
          id: "primary",
          label: "Primary",
          labelZh: "主要",
          classes: [
            "text-[#1C1C1C]",
            "after:content-[''] after:absolute after:w-full after:h-px",
            "after:bottom-0 after:left-0 after:bg-current",
            "after:origin-bottom-right after:scale-x-0",
            "hover:after:origin-bottom-left hover:after:scale-x-100",
            "after:transition-transform after:duration-500",
          ],
        },
        secondary: {
          id: "secondary",
          label: "Secondary",
          labelZh: "次要",
          classes: [
            "text-[#1C1C1C]/60",
          ],
        },
        filled: {
          id: "filled",
          label: "Filled",
          labelZh: "填充",
          classes: [
            "bg-[#1C1C1C] text-[#F9F8F6]",
            "px-6 py-3",
          ],
        },
        ghost: {
          id: "ghost",
          label: "Ghost",
          labelZh: "幽灵",
          classes: [
            "text-[#1C1C1C]/40",
          ],
        },
      },
      slots: [
        { id: "icon", label: "Icon", labelZh: "图标", required: false, type: "icon" },
        { id: "label", label: "Label", labelZh: "文字", required: true, default: "Submit Inquiry", type: "text" },
      ],
      states: {
        hover: [
          "hover:text-[#1C1C1C]",
        ],
        active: ["active:opacity-60"],
        disabled: ["opacity-40 cursor-not-allowed"],
      },
    },

    card: {
      id: "card",
      name: "Card",
      nameZh: "卡片",
      description: "Editorial work list item with bottom border and hover italic effect",
      skeleton: {
        element: "div",
        baseClasses: [
          "bg-[#F9F8F6]",
          "border-b border-[#1C1C1C]/10",
          "transition-colors duration-200",
        ],
      },
      parameters: [
        {
          id: "padding",
          label: "Padding",
          labelZh: "内边距",
          type: "select",
          options: [
            { value: "sm", label: "Small", labelZh: "小", classes: "py-6 md:py-8 px-4" },
            { value: "md", label: "Medium", labelZh: "中", classes: "py-10 md:py-16 px-4" },
            { value: "lg", label: "Large", labelZh: "大", classes: "py-12 md:py-20 px-4" },
          ],
          default: "md",
        },
