  required: {
    button: [
      "bg-[#e0e5ec]",
      "rounded-xl",
      "shadow-[6px_6px_12px_#b8bcc2,-6px_-6px_12px_#ffffff]",
      "hover:shadow-[4px_4px_8px_#b8bcc2,-4px_-4px_8px_#ffffff]",
