                Docs
              </Link>
              <Link
                href="/styles"
                className="text-sm text-gray-400 hover:text-gray-500 transition-colors duration-200"
              >
                All Styles
              </Link>
              <Link
                href="/"
                className="text-sm text-gray-400 hover:text-gray-500 transition-colors duration-200"
              >
                Home
              </Link>
            </div>
          </div>

          <div className="mt-8 pt-6 border-t border-[#b8bcc2]/30 flex items-center justify-between">
