// Minimalist Flat Style Tokens - Precise class mappings for AI
import { createStyleTokens } from "./token-defaults";

export const minimalistFlatTokens = createStyleTokens({
  border: {
    width: "border-2",
    color: "border-black",
    radius: "rounded-none",
  },

  shadow: {
    sm: "shadow-none",
