  transform: translateY(32px) scale(0.9) rotate(-3deg);
  opacity: 0.6;
}

.card-stack-item:nth-child(n+4) {
  z-index: 0;
  transform: translateY(48px) scale(0.85);
  opacity: 0;
  pointer-events: none;
}

