                { label: "MAX",  bg: "#7e2553", size: 40 },
                { label: "99",   bg: "#1a1c2c", border: "#29adff", size: 40, color: "#29adff" },
                { label: "NEW!", bg: "#ffa300", size: 40, color: "#1a1c2c" },
              ].map(({ label, bg, size, color = "#ffffff", border = "#ffffff" }) => (
                <div
                  key={label}
                  style={{
                    width: size,
                    height: size,
                    backgroundColor: bg,
                    border: `4px solid ${border}`,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    fontWeight: 900,
                    fontSize: size > 44 ? "1.1rem" : "0.65rem",
                    color,
                    boxShadow: "2px 2px 0 #000000",
                    letterSpacing: "0.05em",
                  }}
                >
                  {label}
                </div>
              ))}

              {/* Group avatars */}
              <div style={{ display: "flex", marginLeft: 8 }}>
                {["A", "B", "C"].map((letter, i) => (
                  <div
                    key={letter}
                    style={{
                      width: 44,
                      height: 44,
                      backgroundColor: ["#ff004d", "#00e436", "#ffec27"][i],
                      border: "4px solid #ffffff",
                      marginLeft: i === 0 ? 0 : -8,
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      fontWeight: 900,
                      color: i === 2 ? "#1a1c2c" : "#ffffff",
                      fontSize: "0.8rem",
                      zIndex: 3 - i,
                      position: "relative",
                    }}
                  >
                    {letter}
                  </div>
                ))}
              </div>
            </div>
          </div>
        </RevealBlock>
      </Section>

      {/* ================================================================
          SECTION 10 — Footer with pixel art decoration
      ================================================================ */}
      <footer
        style={{
          backgroundColor: "#1a1c2c",
          borderTop: "4px solid #ff004d",
          padding: "48px 24px",
        }}
      >
        <div
          style={{
            maxWidth: 960,
            margin: "0 auto",
          }}
        >
          {/* Pixel sprite row */}
          <div
            style={{
              display: "flex",
              justifyContent: "center",
              gap: 48,
              marginBottom: 40,
              flexWrap: "wrap",
            }}
          >
            <PixelSprite pixels={STAR_PIXELS} pixelSize={6} />
            <PixelSprite pixels={HEART_PIXELS} pixelSize={6} />
            <PixelSprite pixels={COIN_PIXELS} pixelSize={6} />
          </div>

          {/* Pixel divider */}
          <div
            style={{
              display: "flex",
              justifyContent: "center",
              gap: 2,
              marginBottom: 32,
              flexWrap: "wrap",
            }}
          >
            {["#ff004d", "#ffa300", "#ffec27", "#00e436", "#29adff", "#7e2553", "#ff77a8", "#ff004d"].map(
              (color, i) => (
                <div
                  key={i}
                  style={{
                    width: 24,
                    height: 8,
                    backgroundColor: color,
                    imageRendering: "pixelated",
                  }}
                />
              )
            )}
          </div>

          {/* Footer content */}
          <div
            style={{
              textAlign: "center",
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              gap: 12,
            }}
          >
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: 10,
              }}
            >
              <div
                style={{
                  width: 20,
                  height: 20,
                  backgroundColor: "#ff004d",
                  border: "3px solid #ffec27",
                  boxShadow: "3px 3px 0 #ffec27",
                }}
              />
              <span
                style={{
                  fontSize: "1.2rem",
                  fontWeight: 900,
                  color: "#ffec27",
                  textTransform: "uppercase",
                  letterSpacing: "0.2em",
                  textShadow: "3px 3px 0 #ff004d",
                }}
              >
                PIXEL ART
              </span>
              <div
                style={{
                  width: 20,
                  height: 20,
                  backgroundColor: "#ff004d",
                  border: "3px solid #ffec27",
                  boxShadow: "3px 3px 0 #ffec27",
                }}
              />
            </div>

            <p
              style={{
                fontSize: "0.65rem",
                color: "#29adff",
                textTransform: "uppercase",
                letterSpacing: "0.1em",
              }}
            >
              PART OF{" "}
              <Link
                href="/"
                style={{
                  color: "#ffec27",
                  textDecoration: "none",
                  fontWeight: 900,
                }}
              >
                STYLEKIT
              </Link>
            </p>

            <p
              style={{
                fontSize: "0.6rem",
                color: "#5f574f",
                textTransform: "uppercase",
                letterSpacing: "0.1em",
              }}
            >
              8-BIT RETRO GAMING AESTHETICS — PICO-8 PALETTE
            </p>

            <p
              style={{
                fontSize: "0.6rem",
                color: "#5f574f",
                textTransform: "uppercase",
                letterSpacing: "0.1em",
              }}
            >
              &copy; 2026 STYLEKIT. INSERT COIN TO CONTINUE.
            </p>
          </div>
        </div>
      </footer>
    </div>
  );
}

import dynamicImport from "next/dynamic";

export const dynamic = "force-static";

export const metadata = {
  title: "Pixel Art Showcase - StyleKit",
  description: "Live demonstration of Pixel Art design style with retro 8-bit game aesthetics.",
};

const ShowcaseContent = dynamicImport(() => import("./_content"), {
  loading: () => <div className="min-h-screen" />,
});

export default function PixelArtShowcasePage() {
  return <ShowcaseContent />;
}

