                      {/* Base (inactive) */}
                      <div
                        className="absolute inset-0 flex items-center justify-center"
                        style={{ backgroundColor: "#f5f5f5" }}
                      >
                        <span className="text-xs font-black uppercase tracking-widest text-black opacity-30">
                          {block.label}
                        </span>
                      </div>
                      {/* Active color block slides in */}
                      <div
                        className="absolute inset-0 flex items-center justify-center"
