                          {btn.label}
                        </span>
                        {!btn.allowed && (
                          <span className="text-[9px] font-black uppercase text-red-500 block mt-0.5">
                            BANNED
                          </span>
                        )}
                        {btn.allowed && (
                          <span className="text-[9px] font-black uppercase text-green-600 block mt-0.5">
                            ALLOWED
                          </span>
                        )}
                      </div>
                    </div>
                  ))}
                </div>

