                <div className="grid grid-cols-1 md:grid-cols-3 gap-0 border-4 border-black overflow-hidden mb-6">
                  {[
                    { label: "Red Slide", baseBg: "#ff0000", revealBg: "#ffcc00", baseText: "#ffffff", revealText: "#000000" },
