  };

  const s = materialStyles[material];

  return (
    <div className={`group p-1.5 rounded-2xl ${s.outer} relative overflow-hidden transition-shadow duration-300 hover:shadow-[0_14px_28px_rgba(0,0,0,0.4)]`}>
