          fill="none"
          stroke="currentColor"
          strokeWidth="0.8"
        />
        <line x1="150" y1="0" x2="150" y2="8" stroke="currentColor" strokeWidth="0.8" />
        <line x1="145" y1="4" x2="155" y2="4" stroke="currentColor" strokeWidth="0.8" />
      </svg>
      <div className="border-l border-r border-b border-[#4a1a4a]/30 px-8 pb-8">
