                    border: "0.5px solid rgba(100,181,246,0.35)",
                  }}
                >
                  Weightless Float
                </div>
                <p className="font-light text-[9px] tracking-wide text-[#c8d0d8] leading-loose mb-6 font-mono">
                  hover 仅允许极轻上浮（约 0.5px）<br />
