                  </p>
                  <p className="font-light text-[9px] text-[#c8d0d8] tracking-wide mt-2 font-mono">
                    hover:–translate-y-0.5 &middot; duration-500
                  </p>
                </div>
              </div>
            </RevealBlock>

            {/* Rule 2: Airy Transitions */}
            <RevealBlock delay={0.12}>
              <div
