                {/* Demo */}
                <button
                  onClick={() => setAiryActive((v) => !v)}
                  className="w-full rounded-lg p-4 font-light text-xs tracking-widest text-left transition-all duration-500"
                  style={{
                    color: airyActive ? "#98d8c8" : "#b0b8c4",
