                </button>
                <p className="font-light text-[9px] text-[#c8d0d8] tracking-wide mt-3 font-mono">
                  active: opacity 0.75 + bg tint &middot; no scale transform
                </p>
              </div>
            </RevealBlock>
          </div>
        </div>
      </section>

