.ns-torii-frame::before {
  content: "";
  position: absolute;
  top: 8px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--ns-red);
  opacity: 0.5;
}

/* Armor-plate clip path */
.ns-armor-clip {
  clip-path: polygon(0 0, calc(100% - 16px) 0, 100% 16px, 100% 100%, 16px 100%, 0 calc(100% - 16px));
}

/* Smoke overlay */
.ns-smoke::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 80%, rgba(220, 38, 38, 0.04) 0%, transparent 70%);
  pointer-events: none;
}

/* Scan line overlay */
.ns-scanlines::before {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 2px,
    rgba(0, 0, 0, 0.08) 2px,
    rgba(0, 0, 0, 0.08) 4px
  );
  pointer-events: none;
}

.neon-samurai-filter { filter: brightness(1.05) contrast(1.02); }

.neon-samurai-focus { outline: 2px solid var(--neon-samurai-primary, currentColor); outline-offset: 2px; }

/* Additional techniques */
