const paletteSwatches = [
  { name: "Sakura Pink", hex: "#F9A8D4", label: "Primary" },
  { name: "Warm Cream", hex: "#FFF7ED", label: "Background" },
  { name: "Soft Lavender", hex: "#A78BFA", label: "Secondary" },
  { name: "Aqua Mist", hex: "#67E8F9", label: "Tertiary" },
