// Film Noir Style Tokens
import { createStyleTokens } from "./token-defaults";

export const filmNoirTokens = createStyleTokens({
  border: {
    width: "border-b",
    color: "border-neutral-800",
    radius: "rounded-none",
    style: "border-solid",
  },

  shadow: {
    sm: "shadow-sm",
    md: "shadow-md",
    lg: "shadow-lg",
    none: "shadow-none",
    hover: "shadow-lg",
    focus: "ring-1 ring-neutral-600",
    colored: {
      crimson: "shadow-[0_4px_20px_rgba(196,30,58,0.2)]",
      gold: "shadow-[0_4px_20px_rgba(212,175,55,0.15)]",
    },
  },

  interaction: {
    hoverScale: "hover:bg-neutral-800/80",
    transition: "transition-colors duration-500",
  },

  typography: {
    heading: "font-serif italic",
    body: "font-sans",
    mono: "font-mono",
    sizes: {
      hero: "text-5xl md:text-7xl lg:text-8xl",
      h1: "text-4xl md:text-5xl",
      h2: "text-2xl md:text-3xl",
      h3: "text-xl md:text-2xl",
      body: "text-sm md:text-base",
      small: "text-xs",
    },
  },

  spacing: {
    section: "py-20 md:py-32",
    container: "px-8 md:px-12",
    card: "p-8",
    gap: {
      sm: "gap-4",
      md: "gap-6",
      lg: "gap-10",
    },
  },

  colors: {
    background: {
      primary: "bg-[#0a0a0a]",
      secondary: "bg-neutral-900",
      accent: ["bg-neutral-800", "bg-[#c41e3a]"],
    },
    text: {
      primary: "text-neutral-100",
      secondary: "text-neutral-400",
      muted: "text-neutral-600",
    },
    button: {
      primary: "bg-neutral-100 text-neutral-950",
      secondary: "bg-transparent border border-neutral-500 text-neutral-300",
      danger: "bg-[#c41e3a] text-white",
    },
  },

  forbidden: {
    classes: [
      "bg-blue-", "bg-green-", "bg-pink-", "bg-purple-", "bg-yellow-",
      "rounded-2xl", "rounded-3xl", "rounded-full",
      "shadow-[0_0_", "text-shadow",
      "bg-gradient-to-r from-pink", "bg-gradient-to-r from-blue",
      "animate-bounce", "animate-spin",
    ],
    patterns: [
      "^bg-(?:blue|green|pink|purple|yellow|cyan|teal|indigo|violet|fuchsia)-",
      "^rounded-(?:2xl|3xl|full)",
      "^shadow-\\[0_0_",
      "^animate-(?:bounce|spin|wiggle)",
    ],
    reasons: {
      "bg-blue-": "Film Noir uses grayscale only; no colored backgrounds",
      "rounded-2xl": "Film Noir uses sharp corners or minimal rounding",
      "shadow-[0_0_": "No glow effects; use directional shadows for drama",
      "animate-bounce": "Playful animations break the noir atmosphere",
    },
  },

  required: {
    button: ["font-serif", "italic", "tracking-wide", "transition-colors"],
    card: ["bg-neutral-900", "relative", "overflow-hidden"],
    input: ["bg-neutral-950", "border-b", "font-serif", "focus:outline-none"],
  },
});

// Film Noir Component Recipes
import {
  sizeParam,
  fullWidthParam,
  buttonSlots,
  cardSlots,
  inputSlots,
  variant,
  createStyleRecipes,
} from "./factory";

export const filmNoirRecipes = createStyleRecipes("film-noir", "Film Noir", {
  button: {
    id: "button",
    name: "Button",
    nameZh: "按钮",
    description: "Dramatic high-contrast button with serif accents",
    skeleton: {
      element: "button",
      baseClasses: ["font-serif", "tracking-wide", "rounded-none", "transition-all duration-200"],
    },
    parameters: [
      sizeParam({ sm: "px-4 py-1.5 text-sm", md: "px-6 py-2.5 text-base", lg: "px-8 py-3.5 text-lg" }),
      fullWidthParam,
    ],
    variants: {
      primary: variant("primary", "Primary", "主要", ["bg-neutral-100 text-neutral-950"]),
      danger: variant("danger", "Danger", "警告", ["bg-[#c41e3a] text-white"]),
    },
    slots: buttonSlots("Enter"),
    states: {
      hover: ["hover:bg-neutral-200"],
      active: ["active:scale-[0.98]"],
      disabled: ["opacity-50 cursor-not-allowed"],
    },
  },
  card: {
    id: "card",
    name: "Card",
    nameZh: "卡片",
    description: "Dark dramatic card with stark contrast",
    skeleton: {
      element: "div",
      baseClasses: ["bg-neutral-900", "border border-neutral-700", "rounded-none", "overflow-hidden"],
    },
    parameters: [{
      id: "padding", label: "Padding", labelZh: "内边距", type: "select",
      options: [
        { value: "sm", label: "Small", labelZh: "小", classes: "p-4" },
        { value: "md", label: "Medium", labelZh: "中", classes: "p-6" },
        { value: "lg", label: "Large", labelZh: "大", classes: "p-8" },
      ],
      default: "md",
    }],
    variants: { default: variant("default", "Default", "默认", []) },
    slots: cardSlots("Film Noir", "Shadows and intrigue"),
    states: { hover: ["hover:border-neutral-500"] },
  },
  input: {
    id: "input",
    name: "Input",
    nameZh: "输入框",
    description: "Dark input with high-contrast focus state",
    skeleton: {
      element: "input",
      baseClasses: ["w-full", "bg-[#0a0a0a]", "border border-neutral-700", "text-neutral-100", "placeholder:text-neutral-500", "focus:outline-none", "font-serif", "rounded-none", "transition-all duration-200"],
    },
    parameters: [sizeParam({ sm: "px-3 py-2 text-sm", md: "px-4 py-2.5 text-base", lg: "px-5 py-3 text-lg" })],
    variants: { default: variant("default", "Default", "默认", []) },
    slots: inputSlots("Search..."),
    states: {
      focus: ["focus:border-neutral-400"],
      disabled: ["opacity-50 cursor-not-allowed"],
    },
  },
});

import type { DesignStyle } from "./types";

export const arcadeCrt: DesignStyle = {
  slug: "arcade-crt",
  name: "街机CRT",
  nameEn: "Arcade CRT",
  description:
    "80-90年代街机显示器美学，包含扫描线、屏幕曲率、霓虹辉光和RGB色差效果。适合游戏、复古科技、创意项目。",
  descriptionEn:
    "80-90s arcade monitor aesthetics featuring scanlines, screen curvature, neon glow, and RGB chromatic aberration effects. Ideal for gaming, retro tech, and creative projects.",
  cover: "/styles/arcade-crt.svg",
  styleType: "visual",
  tags: ["retro", "high-contrast"],
  category: "retro",
  colors: {
    primary: "#39ff14",
    secondary: "#050505",
    accent: ["#ff00ff", "#00ffff", "#ff2a2a", "#FFFF00", "#ff8533"],
  },
  keywords: ["CRT", "scanlines", "retro gaming", "arcade", "pixel", "neon glow", "chromatic aberration", "retro", "vintage", "nostalgic"],
  keywordsEn: ["CRT effect", "arcade style", "scanlines", "retro gaming ui", "CRT screen", "neon glow", "chromatic aberration", "pixel font", "80s arcade", "phosphor glow", "screen curvature", "retro game website"],

  philosophy: `Arcade CRT 风格再现了80-90年代街机CRT显示器的怀旧辉光。

核心理念：
- 扫描线叠加：所有内容区域使用 repeating-linear-gradient 扫描线效果
- 霓虹辉光：关键元素使用 text-shadow/box-shadow 发光效果
- 像素字体：所有文字使用 monospace 字体
- 极暗背景：近乎纯黑的背景最大化霓虹对比度
- RGB色差：标题使用品红和青色偏移的 text-shadow
- 高饱和度：仅使用高饱和度霓虹色

设计原则：
- 视觉一致性：所有组件必须遵循统一的视觉语言，从色彩到字体到间距保持谐调
- 层次分明：通过颜色深浅、字号大小、留白空间建立清晰的信息层级
- 交互反馈：每个可交互元素都必须有明确的 hover、active、focus 状态反馈
- 响应式适配：设计必须在移动端、平板、桌面端上保持一致的体验
- 无障碍性：确保色彩对比度符合 WCAG 2.1 AA 标准，所有交互元素可键盘访问`,

  philosophyEn: `Arcade CRT style recreates the nostalgic glow of 80-90s arcade CRT monitors.

Core principles:
- Scanline overlay: all content areas use repeating-linear-gradient scanline effects
- Neon glow: key elements use text-shadow/box-shadow glow effects
- Pixel fonts: all text uses monospace fonts
- Ultra-dark backgrounds: near-pure black backgrounds maximize neon contrast
- RGB chromatic aberration: headings use magenta and cyan offset text-shadow
- High saturation: only high-saturation neon colors are used`,

  doList: [
    "Use scanline overlay on all content areas",
