                    title: "White Tint",
                    code: "bg-white/30–70",
                    visual: "bg-white/50",
                    note: "Controls opacity of the frosted overlay",
                  },
                  {
                    title: "Glass Border",
                    code: "border border-white/40",
                    visual: "border-2 border-white/60",
