// Anti Design Component Recipes
import {
  sizeParam,
  fullWidthParam,
  buttonSlots,
  cardSlots,
  inputSlots,
  variant,
  createStyleRecipes,
} from "./factory";

export const antiDesignRecipes = createStyleRecipes("anti-design", "Anti Design", {
  button: {
    id: "button",
    name: "Button",
    nameZh: "按钮",
    description: "Intentionally chaotic button breaking design rules",
    skeleton: {
      element: "button",
      baseClasses: ["font-mono", "font-black", "uppercase", "rounded-none", "transition-all duration-100"],
    },
    parameters: [
      sizeParam({ sm: "px-3 py-1.5 text-sm", md: "px-5 py-2.5 text-base", lg: "px-7 py-3.5 text-lg" }),
      fullWidthParam,
    ],
    variants: {
      primary: variant("primary", "Primary", "主要", ["bg-[#FF0000] text-white border-4 border-black"]),
      yellow: variant("yellow", "Yellow", "黄色", ["bg-[#FFFF00] text-black border-4 border-black"]),
    },
    slots: buttonSlots("CLICK!!!"),
    states: {
      hover: ["hover:rotate-1 hover:scale-105"],
      active: ["active:scale-95"],
      disabled: ["opacity-50 cursor-not-allowed"],
    },
  },
  card: {
    id: "card",
    name: "Card",
    nameZh: "卡片",
    description: "Mismatched chaotic card",
    skeleton: {
      element: "div",
      baseClasses: ["bg-[#FFFF00]", "border-4 border-black", "rounded-none", "overflow-hidden"],
    },
    parameters: [{
      id: "padding", label: "Padding", labelZh: "内边距", type: "select",
      options: [
        { value: "sm", label: "Small", labelZh: "小", classes: "p-3" },
        { value: "md", label: "Medium", labelZh: "中", classes: "p-5" },
        { value: "lg", label: "Large", labelZh: "大", classes: "p-8" },
      ],
      default: "md",
    }],
    variants: { default: variant("default", "Default", "默认", []) },
    slots: cardSlots("ANTI DESIGN", "Rules are meant to be broken"),
    states: { hover: ["hover:-rotate-1"] },
  },
  input: {
    id: "input",
    name: "Input",
    nameZh: "输入框",
    description: "Deliberately ugly input",
    skeleton: {
      element: "input",
      baseClasses: ["w-full", "bg-white", "border-4 border-black", "text-black", "placeholder:text-black/40", "focus:outline-none", "font-mono", "font-black", "rounded-none", "transition-all duration-100"],
    },
    parameters: [sizeParam({ sm: "px-3 py-1.5 text-sm", md: "px-4 py-2.5 text-base", lg: "px-5 py-3 text-lg" })],
    variants: { default: variant("default", "Default", "默认", []) },
    slots: inputSlots("TYPE HERE!!!"),
    states: {
      focus: ["focus:bg-[#FFFF00] focus:border-[#FF0000]"],
      disabled: ["opacity-50 cursor-not-allowed"],
    },
  },
});

// Holographic Style Tokens
import { createStyleTokens } from "./token-defaults";

export const holographicTokens = createStyleTokens({
  border: {
    radius: "rounded-2xl",
    width: "border",
    color: "border-white/10",
    style: "border-solid",
  },

  shadow: {
    sm: "shadow-[0_0_15px_rgba(147,51,234,0.2)]",
    md: "shadow-[0_0_25px_rgba(147,51,234,0.4)]",
    lg: "shadow-[0_0_50px_rgba(147,51,234,0.6)]",
    none: "shadow-none",
    hover: "shadow-[0_0_30px_rgba(147,51,234,0.4)]",
    focus: "shadow-[0_0_20px_rgba(147,51,234,0.4)]",
    colored: {
      purple: "shadow-[0_0_20px_rgba(147,51,234,0.5)]",
      pink: "shadow-[0_0_20px_rgba(255,0,128,0.5)]",
      cyan: "shadow-[0_0_20px_rgba(0,212,255,0.5)]",
    },
  },

  interaction: {
    hoverScale:
      "hover:shadow-[0_0_30px_rgba(147,51,234,0.4)] hover:border-purple-400/30 hover:scale-[1.02]",
    transition: "transition-all duration-500",
  },

  typography: {
    heading: "font-sans font-bold",
    body: "font-sans text-sm",
    mono: "font-mono",
    sizes: {
      hero: "text-5xl md:text-7xl lg:text-8xl",
      h1: "text-4xl md:text-6xl",
      h2: "text-2xl md:text-4xl",
      h3: "text-xl md:text-2xl",
      body: "text-sm md:text-base",
      small: "text-xs",
    },
  },

  spacing: {
    section: "py-16 px-6 md:px-8",
    container: "px-4 md:px-8",
    card: "p-6",
    gap: {
      sm: "gap-4",
      md: "gap-6",
      lg: "gap-8",
    },
  },

  colors: {
    background: {
      primary: "bg-[#0a0a1f]",
      secondary: "bg-[#1a0b2e]",
      accent: ["bg-purple-500/10", "bg-pink-500/10", "bg-cyan-500/10"],
    },
    text: {
      primary: "text-white",
      secondary: "text-white/70",
      muted: "text-white/40",
    },
    button: {
      primary:
        "bg-gradient-to-r from-[#ff0080] via-[#7928ca] to-[#00d4ff] text-white",
      secondary: "bg-white/10 text-white border border-white/20",
      danger: "bg-red-500/80 text-white",
    },
  },

  forbidden: {
    classes: [
      "bg-white",
      "bg-gray-50",
      "bg-gray-100",
      "shadow-sm",
      "shadow-md",
      "shadow-lg",
      "text-gray-900",
      "text-black",
      "rounded-none",
      "border-black",
      "border-gray-300",
    ],
    patterns: [
      "^bg-white",
      "^bg-gray-[1-3]",
      "^bg-slate-[1-3]",
      "^shadow-(?!\\[)",
    ],
    reasons: {
      "bg-white":
        "Holographic style requires dark backgrounds to make prismatic effects pop",
      "shadow-md":
        "Use prismatic glow shadows: shadow-[0_0_20px_rgba(147,51,234,0.5)]",
      "text-black": "Use text-white or gradient text on dark backgrounds",
    },
  },

  required: {
    button: [
      "rounded-",
      "bg-gradient-",
      "transition-all",
      "shadow-[0_0_",
    ],
    card: ["backdrop-blur", "bg-white/", "rounded-", "border"],
    input: [
      "backdrop-blur",
      "bg-white/",
      "rounded-",
      "focus:border-purple",
      "focus:shadow-[0_0_",
    ],
  },
});

// Holographic Component Recipes
import {
  sizeParam,
  fullWidthParam,
  buttonSlots,
  cardSlots,
  inputSlots,
  variant,
  createStyleRecipes,
} from "./factory";

export const holographicRecipes = createStyleRecipes("holographic", "Holographic", {
  button: {
    id: "button",
    name: "Button",
    nameZh: "按钮",
