                    e.currentTarget.style.backgroundColor =
                      "rgba(44,44,44,0.025)";
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.borderLeftColor =
                      "rgba(44,44,44,0.1)";
                    e.currentTarget.style.backgroundColor = "#f8f5f0";
                  }}
                >
                  <div className="mb-6">
                    <span
                      className="font-serif font-light"
                      style={{
                        fontSize: "3.5rem",
                        color: "rgba(44,44,44,0.12)",
