                  style={{
                    borderBottom: `1px solid ${inputFocused ? "#6b7b6e" : "rgba(196,185,168,0.5)"}`,
                    color: "#2c2c2c",
                    transition: "border-color 700ms ease-in-out",
                    caretColor: "#6b7b6e",
