                  style={{
                    borderBottom: "1px solid rgba(196,185,168,0.5)",
                    color: "#2c2c2c",
                    transition: "border-color 700ms ease-in-out",
                  }}
                  onFocus={(e) => {
                    e.currentTarget.style.borderBottomColor = "#6b7b6e";
                  }}
                  onBlur={(e) => {
                    e.currentTarget.style.borderBottomColor =
                      "rgba(196,185,168,0.5)";
                  }}
