                  </p>
                </div>
              </div>
            </RevealBlock>

            {/* Body */}
            <RevealBlock>
              <div
                className="grid grid-cols-12 items-start gap-8 pb-12"
                style={{ borderBottom: "1px solid rgba(44,44,44,0.08)" }}
              >
                <div className="col-span-3">
                  <span
                    className="font-serif font-light text-xs tracking-widest"
