      {/* ---------------------------------------------------------------- */}
      {/* Additional: Interaction States                                   */}
      {/* ---------------------------------------------------------------- */}
      <section className="py-24 px-8" style={{ backgroundColor: "#f8f5f0" }}>
        <div className="max-w-6xl mx-auto">
          <RevealBlock className="text-center mb-16">
