// Monochrome Component Recipes
import {
  sizeParam,
  fullWidthParam,
  buttonSlots,
  cardSlots,
  inputSlots,
  variant,
  createStyleRecipes,
} from "./factory";

export const monochromeRecipes = createStyleRecipes("monochrome", "Monochrome", {
  button: {
    id: "button",
    name: "Button",
    nameZh: "按钮",
