        labelZh: "内边距",
        type: "select",
        options: [
          { value: "sm", label: "Small", labelZh: "小", classes: "p-3" },
          { value: "md", label: "Medium", labelZh: "中", classes: "p-5" },
          { value: "lg", label: "Large", labelZh: "大", classes: "p-7" },
        ],
        default: "md",
      },
    ],
    variants: {
      default: variant("default", "Default", "默认", []),
    },
    slots: cardSlots("Monochrome", "Pure black and white"),
    states: {
      hover: ["hover:shadow-sm"],
    },
  },

  input: {
    id: "input",
    name: "Input",
    nameZh: "输入框",
    description: "Sharp-edged input with clean border",
    skeleton: {
      element: "input",
      baseClasses: [
        "w-full",
        "bg-[#fafafa]",
        "border border-[#e5e5e5]",
        "text-[#111111]",
        "placeholder:text-[#666666]/50",
        "focus:outline-none",
        "rounded-none",
        "transition-all duration-200",
      ],
    },
    parameters: [
      sizeParam({
        sm: "px-3 py-1.5 text-sm",
        md: "px-4 py-2.5 text-base",
        lg: "px-5 py-3.5 text-lg",
      }),
    ],
    variants: {
      default: variant("default", "Default", "默认", []),
    },
    slots: inputSlots("Type here..."),
    states: {
      focus: ["focus:border-[#111111]"],
      disabled: ["opacity-50 cursor-not-allowed"],
    },
  },
});

import type { DesignStyle } from "./types";

export const terracotta: DesignStyle = {
  slug: "terracotta",
  name: "赤陶暖调",
  nameEn: "Terracotta",
  description:
    "地中海赤陶与暖色大地的设计风格，温暖的陶土色调、粗糙手工质感和自然纹理。适合生活方式品牌、餐饮、旅行和手工艺品展示。",
  descriptionEn:
    "A Mediterranean terracotta and warm earth design style with warm clay tones, rough handcrafted textures, and natural patterns. Ideal for lifestyle brands, dining, travel, and artisan product showcases.",
  cover: "/styles/terracotta.svg",
  styleType: "visual",
  tags: [],
  category: "minimal",
  colors: {
