    container: "px-6 md:px-12 lg:px-20",
    card: "p-8",
    gap: {
      sm: "gap-3 md:gap-4",
      md: "gap-5 md:gap-8",
      lg: "gap-8 md:gap-12",
    },
  },

  colors: {
