      description:
        "Intricate pookalam flower carpets spread across courtyards in layered concentric rings. Snake boat races animate the backwaters as communities feast on sadhya.",
      color: "#2a9d8f",
      accent: "#d4af37",
    },
  ]

  const paletteColors = [
    {
      name: "Vermillion",
