        "bg-gradient-to-br from-[#f0e6d0] to-[#c9a74e]/15",
      ]),
      crimson: variant("crimson", "Crimson", "深红", [
        "border-[#8b1a1a]/60",
        "bg-gradient-to-br from-[#f0e6d0] to-[#8b1a1a]/10",
      ]),
    },
    slots: cardSlots(),
    states: {
